using System.Collections;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ChargingAntennasEffect", menuName = "Data/Battle/Effects/Austra/ChargingAntennas Effect")]
public class ChargingAntennasEffect : Effect
{
	[SerializeField]
	private int turnToTrigger;

	[SerializeField]
	private OmenLogicActionFace omenLogicActionFace;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetEffectDescription(-2);
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return GetEffectDescription(amount);
	}

	private string GetEffectDescription(int amount)
	{
		string arg = base.localizationManager.GetLocalizedAtTheEndOfYourTurn().LowercaseFirst() + base.localizationManager.GetLocalizedSpace() + omenLogicActionFace.ActionFace.BattleAction.GetActionDescription(amount);
		return Smart.Format(GetLocalizedDescription(), turnToTrigger, arg) + "\n" + base.localizationManager.GetLocalizedThisPurifyCanTriggerCritical();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter >= turnToTrigger)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfflictionReliefHealbotForcefulStreamAction(ActivateEffectCoroutine(effectAmount, effectOwner));
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		}
		return effectAmount;
	}

	private IEnumerator ActivateEffectCoroutine(int effectAmount, GameObject effectOwner)
	{
		yield return new WaitForSeconds(0.2f);
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		omenLogicActionFace.ActivateOmen(effectAmount);
		yield return new WaitForSeconds(0.6f);
	}
}
